import { getSortedTree } from './get-sorted-tree.js';
import { getColorPalette } from '../../core/functions/get-color-palette.js';
import {
  ColorPalette,
  CustomColorPalette,
} from '../../core/types/color-palette.js';
import { InternalTreeMapData } from '../types/internal.js';
import { TreeMapRootNode } from '../types/treemap.js';

/**
 * Function responsible to map the consumer dataset to the internal one.
 * For now
 * @param tree
 * @param unit
 * @param colorPalette
 */
export function mapToInternalTreemapData(
  tree: TreeMapRootNode,
  unit: string | undefined,
  colorPalette: ColorPalette | CustomColorPalette,
): InternalTreeMapData {
  const sortedTree = getSortedTree(tree);

  const nodeArray = sortedTree.children.map((clusterNode, index) => ({
    ...clusterNode,
    color: getColorPalette(clusterNode.name, index, colorPalette),
  }));

  return {
    tree: {
      ...tree,
      children: nodeArray,
    },
    unit,
  };
}
